import type { Term } from "../../app/generated/prisma/client";

export type UpperYearCourse = {
  code: string;
  title: string;
  description: string;
  yearLevel: number;
  termsOffered: Term[];
  isCore: boolean;
  prerequisites: string;
  antirequisites: string;
};

/**
 * Real, verified upper-year courses per discipline, sourced from the
 * Western Academic Calendar (westerncalendar.uwo.ca) and eng.uwo.ca
 * department pages. Ratings/reviews are synthetic — course codes, titles,
 * prerequisites, and antirequisites are not: prerequisites/antirequisites
 * are pulled verbatim from the live calendar as of 2026-08.
 *
 * Two corrections from the original program list, confirmed against the
 * live calendar:
 * - "Computer Engineering" was discontinued as a standalone Western degree
 *   in September 2022. Its courses are folded into Electrical Engineering
 *   below (ECE now serves both) rather than seeded as a separate program.
 * - Integrated Engineering's upper-year prefix is `IE`, not `ES` — `ES` is
 *   only used for the four first-year common courses.
 *
 * Integrated Engineering has fewer dedicated courses than the other core
 * disciplines (11) — that's a real, small-catalogue program, not a
 * seeding shortcut.
 *
 * Green Process Engineering has been removed entirely (see DISCIPLINES in
 * seed.ts) — it's confirmed discontinued as a standalone program, not just
 * renamed course codes.
 *
 * `aise` and `biomedical` are combined/concurrent degrees (Discipline.
 * isCombinedDegree = true in seed.ts) — students take these alongside a
 * core discipline, and only their own dedicated courses (confirmed on the
 * live calendar under the AISE/BME subjects) are seeded here, not the
 * shared core-discipline courses they also take.
 */
